function run(input) {
  const v = input.value;
  if (typeof v === "number") return Number.isInteger(v) && v >= 0 && v <= 150;
  if (typeof v !== "string" || !/^[0-9]+$/.test(v)) return false;
  return Number(v) <= 150;
}
